package com.example.aiprojectmanager.task.domain;
import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="tasks") @Getter @Setter @NoArgsConstructor
public class Task { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="project_id",nullable=false) private Long projectId; @Column(nullable=false) private String title; @Column(length=2000) private String description; @Enumerated(EnumType.STRING) @Column(nullable=false) private TaskStatus status=TaskStatus.TODO; @Enumerated(EnumType.STRING) @Column(nullable=false) private TaskPriority priority=TaskPriority.MEDIUM; private BigDecimal estimatedHours; private BigDecimal actualHours; private LocalDate startDate; private LocalDate dueDate; @Column(nullable=false) private Integer progressPercentage=0; @Column(name="duration_days",nullable=false) private Integer durationDays=1; @Column(name="sprint_id") private Long sprintId; @Column(name="story_points") private Integer storyPoints=0; @Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt; @Column(name="updated_at",nullable=false) private LocalDateTime updatedAt; @PrePersist void create(){createdAt=updatedAt=LocalDateTime.now();} @PreUpdate void update(){updatedAt=LocalDateTime.now();} }

